fn diag_val(i: i32, j: i32) -> f64 {
    if i == j {
        1.0
    } else {
        0.0
    }
}

fn identity(n: usize) -> Vec<Vec<f64>> {
    let mut matrix = vec![vec![0.0; n]; n]; // Create an n x n matrix initialized with 0.0

    for i in 0..n {
        for j in 0..n {
            matrix[i][j] = diag_val(i as i32, j as i32); // Fill the matrix using diag_val
        }
    }

    matrix
}

fn main() {
    let n = 3; // Example size
    let id_matrix = identity(n);
    
    // Print the identity matrix
    for row in id_matrix {
        println!("{:?}", row);
    }
}